CREATE TABLE AppMetadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE Environments (id TEXT PRIMARY KEY, revision INTEGER NOT NULL CHECK(revision>=1), json TEXT NOT NULL, hash TEXT NOT NULL, name TEXT NOT NULL, description TEXT, componentTypes TEXT NOT NULL, generationId TEXT NOT NULL, deletionState TEXT NOT NULL DEFAULT 'live', savedAt TEXT NOT NULL);
CREATE TABLE ComponentDefinitions (definitionId TEXT NOT NULL, version TEXT NOT NULL, hash TEXT NOT NULL, json TEXT NOT NULL, PRIMARY KEY(definitionId,version));
CREATE TABLE ApplicationSettings (key TEXT PRIMARY KEY, json TEXT NOT NULL);
CREATE TABLE LocalPathMappings (alias TEXT PRIMARY KEY, absolutePath TEXT NOT NULL, verifiedAt TEXT);
CREATE TABLE Secrets (reference TEXT PRIMARY KEY, label TEXT NOT NULL, ciphertext BLOB NOT NULL, createdAt TEXT NOT NULL);
CREATE TABLE SeedPacks (packId TEXT NOT NULL, version TEXT NOT NULL, contentHash TEXT NOT NULL, json TEXT NOT NULL, verifiedAt TEXT NOT NULL, PRIMARY KEY(packId,version));
CREATE TABLE ContentBlobs (hash TEXT PRIMARY KEY, relativePath TEXT NOT NULL UNIQUE, bytes INTEGER NOT NULL CHECK(bytes>=0));
CREATE TABLE PackEntries (packId TEXT NOT NULL, version TEXT NOT NULL, path TEXT NOT NULL, sectionId TEXT, blobHash TEXT NOT NULL REFERENCES ContentBlobs(hash), bytes INTEGER NOT NULL, recordCount INTEGER, indexJson TEXT, PRIMARY KEY(packId,version,path), FOREIGN KEY(packId,version) REFERENCES SeedPacks(packId,version));
CREATE TABLE PackageReferences (ownerKind TEXT NOT NULL CHECK(ownerKind IN ('environment','operation')), ownerId TEXT NOT NULL, applicationId TEXT NOT NULL, packId TEXT NOT NULL, version TEXT NOT NULL, contentHash TEXT NOT NULL, PRIMARY KEY(ownerKind,ownerId,applicationId));
CREATE INDEX PackageReferences_pack ON PackageReferences(packId,version);
CREATE TABLE DataGenerations (id TEXT PRIMARY KEY, environmentId TEXT NOT NULL REFERENCES Environments(id), baselineHash TEXT NOT NULL, validity TEXT NOT NULL CHECK(validity IN ('active','invalidated','retired')), allocatedAt TEXT NOT NULL, invalidatedAt TEXT, reason TEXT, operationId TEXT);
CREATE TABLE DataApplicationRecords (environmentId TEXT NOT NULL REFERENCES Environments(id), componentId TEXT NOT NULL, generationId TEXT NOT NULL REFERENCES DataGenerations(id), baselineHash TEXT NOT NULL, applicationHash TEXT NOT NULL, initializerHash TEXT NOT NULL, stepId TEXT NOT NULL, state TEXT NOT NULL, idempotencyKey TEXT NOT NULL, attempt INTEGER NOT NULL, startedAt TEXT, completedAt TEXT, acceptedStatus INTEGER, assertionsPassed INTEGER, errorCode TEXT, PRIMARY KEY(environmentId,componentId,generationId,baselineHash,applicationHash,initializerHash,stepId));
CREATE TABLE Operations (id TEXT PRIMARY KEY, environmentId TEXT NOT NULL REFERENCES Environments(id), kind TEXT NOT NULL, state TEXT NOT NULL, originalRevision INTEGER NOT NULL, configurationHash TEXT NOT NULL, planJson TEXT NOT NULL, confirmationHash TEXT, confirmedAt TEXT, candidateJson TEXT, json TEXT NOT NULL, createdAt TEXT NOT NULL, completedAt TEXT, resultCode TEXT);
CREATE TABLE OperationSteps (operationId TEXT NOT NULL REFERENCES Operations(id), stepId TEXT NOT NULL, ordinal INTEGER NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, state TEXT NOT NULL, intentJson TEXT NOT NULL, resultJson TEXT, startedAt TEXT NOT NULL, completedAt TEXT, PRIMARY KEY(operationId,stepId));
CREATE TABLE ResourceLedger (resourceId TEXT PRIMARY KEY, installationId TEXT NOT NULL, environmentId TEXT NOT NULL REFERENCES Environments(id), componentId TEXT, kind TEXT NOT NULL CHECK(kind IN ('container','network','volume')), creationRevision INTEGER NOT NULL, generationId TEXT NOT NULL REFERENCES DataGenerations(id), operationId TEXT NOT NULL REFERENCES Operations(id), json TEXT NOT NULL, unresolved INTEGER NOT NULL, createIntent TEXT, deleteIntent TEXT);
PRAGMA user_version=1;
